/**
 * The shared container classes of an ejected project (ADR 0074 D9), in `<package>/block/`:
 * `ContainerSpec` (the settings of one `msm:container` block with the runtime's defaults applied),
 * `BlockEvents` (how a block entity fires its block's events), and copies of the runtime's
 * `MsmStorageBlockEntity`, `ContainerMenus`, `ContainerOpeners`, `HolderInteraction` and
 * `MsmContainerBlockItem` (`engine-mod/src/main/java/dev/mcsupermods/runtime/registry/container/`,
 * Minecraft 26.3, Mojang names) with the names changed: `BlockComponents.Container` is
 * `ContainerSpec`, `MsmBlock.OPEN` is `BlockStateProperties.OPEN`, and events go through
 * `BlockEvents.fireEvent` instead of the runtime's `EventRunner`. The generator's tests compare
 * every code line with the runtime's.
 *
 * @packageDocumentation
 */

/** The source of `ContainerSpec.java`: the settings of an `msm:container` block. */
export function containerSpecJava(blockPackage: string): string {
  return `// Generated by MCSuperMods: msm:container as the runtime's BlockComponents.Container.
package ${blockPackage};

import java.util.Optional;
import net.minecraft.resources.Identifier;

/**
 * The settings of an {@code msm:container} block (ADR 0074 D1) with the defaults applied: {@code rows} of a
 * {@code chest} (default 3), {@code size} of a {@code none} holder (default 1), {@code keep_contents} (a 3-row chest
 * only), {@code hoppers} and {@code comparator} (default true), the open and close sounds (absent: a barrel's) and the
 * {@code on_open} and {@code on_close} events.
 */
public record ContainerSpec(Layout layout, int rows, int size, boolean keepContents, boolean hoppers, boolean comparator,
        Optional<Identifier> openSound, Optional<Identifier> closeSound, Optional<Identifier> onOpen,
        Optional<Identifier> onClose) {
    /** The vanilla screen: a chest of {@code rows} rows (a shulker box with keep-contents), a hopper, a dispenser, none. */
    public enum Layout {
        CHEST,
        HOPPER,
        DISPENSER,
        NONE
    }

    /** The number of slots: {@code 9 * rows} (chest), 5 (hopper), 9 (dispenser) or {@code size} (none). */
    public int slotCount() {
        return switch (layout) {
            case CHEST -> 9 * rows;
            case HOPPER -> 5;
            case DISPENSER -> 9;
            case NONE -> size;
        };
    }
}
`;
}

/** The source of `BlockEvents.java`: a block whose block entity fires its events. */
export function blockEventsJava(blockPackage: string): string {
  return `// Generated by MCSuperMods: the block events a block entity fires.
package ${blockPackage};

import net.minecraft.core.BlockPos;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.player.Player;

/**
 * A container or machine block whose block entity fires events: {@code on_open} and {@code on_close} with the player
 * as self and other, {@code on_start} and {@code on_finish} at the block with no actor (ADR 0074 D1, ADR 0075 D3).
 */
public interface BlockEvents {
    /** Runs the block's event {@code event} at {@code pos}; an event the block does not have does nothing. */
    void fireEvent(Identifier event, ServerLevel level, BlockPos pos, Player player);
}
`;
}

/** The source of `StorageBlockEntity.java`, copied from the runtime's `MsmStorageBlockEntity`. */
export function storageBlockEntityJava(blockPackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's MsmStorageBlockEntity.
package ${blockPackage};

import java.util.List;
import java.util.Optional;
import java.util.stream.IntStream;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.NonNullList;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.ContainerHelper;
import net.minecraft.world.WorldlyContainer;
import net.minecraft.world.entity.ContainerUser;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.entity.RandomizableContainerBlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;

/**
 * The block entity of an {@code msm:container} block (ADR 0074 D2): a {@link RandomizableContainerBlockEntity}, so loot
 * tables, custom names, {@code lock}, the {@code container} item component and {@code /data}, {@code /item} and
 * {@code /loot ... insert} work as on a chest. Items are saved under {@code Items} in vanilla's {@link ContainerHelper}
 * shape.
 *
 * <ul>
 *   <li>Menus per layout through {@link ContainerMenus}; the title is the custom name or the block's name.
 *   <li>Hoppers (D4): every face reaches every slot with {@code hoppers: true}; with {@code false}
 *       {@link #getSlotsForFace} is empty, so vanilla hoppers and Fabric item transfer (whose fallback wraps any
 *       {@code Container} block entity through the same {@link WorldlyContainer} faces) leave the block alone.
 *   <li>Keep-contents (D6): {@link #canPlaceItem} refuses items that cannot go inside container items (hoppers and
 *       commands; the shulker box menu's own slot refuses them in the screen), and {@link #preRemoveSideEffects} drops
 *       nothing: the loot table copies the contents into the item.
 *   <li>Openers (D3) through {@link ContainerOpeners}: the {@code open} property, the sounds, the barrel's scheduled
 *       recheck ({@link #recheckOpen}, from the block's {@code tick}); {@code on_open} and {@code on_close} with the
 *       player as self and other.
 * </ul>
 */
public class StorageBlockEntity extends RandomizableContainerBlockEntity implements WorldlyContainer {
    private final ContainerSpec spec;
    private final int[] allSlots;
    private final ContainerOpeners openers;
    private NonNullList<ItemStack> items;

    public StorageBlockEntity(BlockEntityType<?> type, BlockPos pos, BlockState state, ContainerSpec spec) {
        super(type, pos, state);
        this.spec = spec;
        this.items = NonNullList.withSize(spec.slotCount(), ItemStack.EMPTY);
        this.allSlots = IntStream.range(0, spec.slotCount()).toArray();
        this.openers = new ContainerOpeners(this);
    }

    /** The container settings of the block. */
    public ContainerSpec spec() {
        return spec;
    }

    // Saving: the barrel's shape (a loot table not yet unpacked is saved instead of the items).

    @Override
    protected void loadAdditional(ValueInput input) {
        super.loadAdditional(input);
        items = NonNullList.withSize(getContainerSize(), ItemStack.EMPTY);
        if (!tryLoadLootTable(input)) {
            ContainerHelper.loadAllItems(input, items);
        }
    }

    @Override
    protected void saveAdditional(ValueOutput output) {
        super.saveAdditional(output);
        if (!trySaveLootTable(output)) {
            ContainerHelper.saveAllItems(output, items);
        }
    }

    @Override
    public int getContainerSize() {
        return spec.slotCount();
    }

    @Override
    protected NonNullList<ItemStack> getItems() {
        return items;
    }

    @Override
    protected void setItems(NonNullList<ItemStack> items) {
        this.items = items;
    }

    @Override
    protected Component getDefaultName() {
        return Component.translatable(getBlockState().getBlock().getDescriptionId());
    }

    @Override
    protected AbstractContainerMenu createMenu(int containerId, Inventory inventory) {
        return ContainerMenus.create(spec, containerId, inventory, this);
    }

    // Hoppers, comparators-through-contents and keep-contents (D4, D6)

    @Override
    public boolean canPlaceItem(int slot, ItemStack stack) {
        return !spec.keepContents() || stack.getItem().canFitInsideContainerItems();
    }

    @Override
    public int[] getSlotsForFace(Direction side) {
        return spec.hoppers() ? allSlots : new int[0];
    }

    @Override
    public boolean canPlaceItemThroughFace(int slot, ItemStack stack, Direction side) {
        return spec.hoppers() && canPlaceItem(slot, stack);
    }

    @Override
    public boolean canTakeItemThroughFace(int slot, ItemStack stack, Direction side) {
        return spec.hoppers();
    }

    @Override
    public void preRemoveSideEffects(BlockPos pos, BlockState state) {
        if (!spec.keepContents()) {
            super.preRemoveSideEffects(pos, state); // drops the contents, as every vanilla Container (D5)
        }
    }

    // Openers (D3)

    @Override
    public void startOpen(ContainerUser user) {
        LivingEntity entity = user.getLivingEntity();
        if (!remove && !entity.isSpectator()) {
            openers.incrementOpeners(entity, getLevel(), getBlockPos(), getBlockState(), user.getContainerInteractionRange());
            if (entity instanceof Player player) {
                fire(spec.onOpen(), player);
            }
        }
    }

    @Override
    public void stopOpen(ContainerUser user) {
        LivingEntity entity = user.getLivingEntity();
        if (!remove && !entity.isSpectator()) {
            openers.decrementOpeners(entity, getLevel(), getBlockPos(), getBlockState());
            if (entity instanceof Player player) {
                fire(spec.onClose(), player);
            }
        }
    }

    @Override
    public List<ContainerUser> getEntitiesWithContainerOpen() {
        return openers.getEntitiesWithContainerOpen(getLevel(), getBlockPos());
    }

    /** The barrel's scheduled recheck: closes the container when no player in range still has it open. */
    public void recheckOpen() {
        if (!remove) {
            openers.recheckOpeners(getLevel(), getBlockPos(), getBlockState());
        }
    }

    /** Players with this container open now. */
    public int openerCount() {
        return openers.getOpenerCount();
    }

    /** Fires {@code event} (on_open or on_close) at the block with {@code player} as self and other. */
    void fire(Optional<Identifier> event, Player player) {
        if (event.isPresent() && getLevel() instanceof ServerLevel server && getBlockState().getBlock() instanceof BlockEvents block) {
            block.fireEvent(event.get(), server, getBlockPos(), player);
        }
    }
}
`;
}

/** The source of `ContainerMenus.java`, copied from the runtime's `ContainerMenus`. */
export function containerMenusJava(blockPackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's ContainerMenus.
package ${blockPackage};

import net.minecraft.world.Container;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.inventory.ChestMenu;
import net.minecraft.world.inventory.DispenserMenu;
import net.minecraft.world.inventory.HopperMenu;
import net.minecraft.world.inventory.MenuType;
import net.minecraft.world.inventory.ShulkerBoxMenu;

/**
 * The vanilla menu of each container layout (ADR 0074 D1): {@code chest} is a {@link ChestMenu} of {@code rows} rows
 * ({@code GENERIC_9x1} to {@code GENERIC_9x6}), or a {@link ShulkerBoxMenu} with {@code keep_contents}; {@code hopper} a
 * {@link HopperMenu}; {@code dispenser} a {@link DispenserMenu}; {@code none} has no menu. Vanilla menu types need no
 * client code: the client opens the vanilla screen for them. Never a {@code Slot} of our own (its constructor differs on
 * 26.4, F7 of the plan).
 */
public final class ContainerMenus {
    private ContainerMenus() {}

    /** The menu for {@code container}, or null for the {@code none} layout. */
    public static AbstractContainerMenu create(ContainerSpec spec, int containerId, Inventory inventory, Container container) {
        return switch (spec.layout()) {
            case CHEST -> spec.keepContents()
                    ? new ShulkerBoxMenu(containerId, inventory, container)
                    : new ChestMenu(chestType(spec.rows()), containerId, inventory, container, spec.rows());
            case HOPPER -> new HopperMenu(containerId, inventory, container);
            case DISPENSER -> new DispenserMenu(containerId, inventory, container);
            case NONE -> null;
        };
    }

    /** The generic chest menu type of {@code rows} rows of nine. */
    static MenuType<ChestMenu> chestType(int rows) {
        return switch (rows) {
            case 1 -> MenuType.GENERIC_9x1;
            case 2 -> MenuType.GENERIC_9x2;
            case 3 -> MenuType.GENERIC_9x3;
            case 4 -> MenuType.GENERIC_9x4;
            case 5 -> MenuType.GENERIC_9x5;
            case 6 -> MenuType.GENERIC_9x6;
            default -> throw new IllegalArgumentException("rows " + rows + " (expected 1..6)");
        };
    }
}
`;
}

/** The source of `ContainerOpeners.java`, copied from the runtime's `ContainerOpeners`. */
export function containerOpenersJava(blockPackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's ContainerOpeners.
package ${blockPackage};

import java.util.Optional;
import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.Slot;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.entity.ContainerOpenersCounter;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;

/**
 * The opener counter of a {@link StorageBlockEntity} (ADR 0074 D3), following the barrel's rule: the first player to
 * open the screen sets {@code open=true} and plays {@code open_sound}, the last to close it sets {@code open=false} and
 * plays {@code close_sound}; vanilla's counter schedules a block tick to recheck the players in range, which the block's
 * {@code tick} forwards to {@link StorageBlockEntity#recheckOpen}. Default sounds are the barrel's (the targets'
 * {@code BlockFacts.containerSounds}).
 */
final class ContainerOpeners extends ContainerOpenersCounter {
    private final StorageBlockEntity owner;

    ContainerOpeners(StorageBlockEntity owner) {
        this.owner = owner;
    }

    @Override
    protected void onOpen(Level level, BlockPos pos, BlockState state) {
        playSound(level, pos, sound(owner.spec().openSound(), SoundEvents.BARREL_OPEN));
        setOpen(level, pos, state, true);
    }

    @Override
    protected void onClose(Level level, BlockPos pos, BlockState state) {
        playSound(level, pos, sound(owner.spec().closeSound(), SoundEvents.BARREL_CLOSE));
        setOpen(level, pos, state, false);
    }

    @Override
    protected void openerCountChanged(Level level, BlockPos pos, BlockState state, int previous, int now) {}

    /** Whether {@code player}'s open menu shows this container: any of its slots belongs to the block entity. */
    @Override
    public boolean isOwnContainer(Player player) {
        for (Slot slot : player.containerMenu.slots) {
            if (slot.container == owner) {
                return true;
            }
        }
        return false;
    }

    /** The configured sound when registered (an unknown id is a load error at start-up), else {@code fallback}. */
    static SoundEvent sound(Optional<Identifier> id, SoundEvent fallback) {
        return id.flatMap(BuiltInRegistries.SOUND_EVENT::getOptional).orElse(fallback);
    }

    private static void playSound(Level level, BlockPos pos, SoundEvent sound) {
        level.playSound(null, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, sound, SoundSource.BLOCKS, 0.5f,
                level.getRandom().nextFloat() * 0.1f + 0.9f);
    }

    private static void setOpen(Level level, BlockPos pos, BlockState state, boolean open) {
        if (state.hasProperty(BlockStateProperties.OPEN) && state.getValue(BlockStateProperties.OPEN) != open) {
            level.setBlock(pos, state.setValue(BlockStateProperties.OPEN, open), Block.UPDATE_ALL);
        }
    }
}
`;
}

/** The source of `HolderInteraction.java`, copied from the runtime's `HolderInteraction`. */
export function holderInteractionJava(blockPackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's HolderInteraction.
package ${blockPackage};

import net.minecraft.world.Container;
import net.minecraft.world.Containers;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;

/**
 * The holder's put-in and take-out (ADR 0074 D1, layout {@code none}): using the block with an item puts as much of the
 * held stack as fits into the first slot that takes it; using it with an empty hand takes the last filled slot out. Both
 * respect {@code canPlaceItem} and the slot's stack limit. The item is not drawn on the block (limit C9).
 */
public final class HolderInteraction {
    private HolderInteraction() {}

    /**
     * Moves as much of {@code held} as fits into the first slot of {@code container} that takes any of it (an empty
     * slot or one holding the same item and components), consuming it from {@code held} unless {@code player} has
     * infinite materials. Returns the number of items moved, 0 when no slot takes it.
     */
    public static int putIn(Container container, ItemStack held, Player player) {
        if (held.isEmpty()) {
            return 0;
        }
        for (int slot = 0; slot < container.getContainerSize(); slot++) {
            if (!container.canPlaceItem(slot, held)) {
                continue;
            }
            ItemStack inSlot = container.getItem(slot);
            int limit = Math.min(container.getMaxStackSize(held), held.getMaxStackSize());
            int moved;
            if (inSlot.isEmpty()) {
                moved = Math.min(held.getCount(), limit);
                container.setItem(slot, held.copyWithCount(moved));
            } else if (ItemStack.isSameItemSameComponents(inSlot, held) && inSlot.getCount() < limit) {
                moved = Math.min(held.getCount(), limit - inSlot.getCount());
                inSlot.grow(moved);
            } else {
                continue;
            }
            held.consume(moved, player);
            container.setChanged();
            return moved;
        }
        return 0;
    }

    /**
     * Takes the whole stack of the last filled slot out of {@code container} into {@code player}'s inventory (dropped
     * at the player when it is full). Returns the stack taken, empty when the container is empty.
     */
    public static ItemStack takeOut(Container container, Player player) {
        for (int slot = container.getContainerSize() - 1; slot >= 0; slot--) {
            if (!container.getItem(slot).isEmpty()) {
                ItemStack taken = container.removeItemNoUpdate(slot);
                container.setChanged();
                ItemStack given = taken.copy();
                if (!player.getInventory().add(given)) {
                    Containers.dropItemStack(player.level(), player.getX(), player.getY(), player.getZ(), given);
                }
                return taken;
            }
        }
        return ItemStack.EMPTY;
    }
}
`;
}

/** The source of `ContainerBlockItem.java`, copied from the runtime's `MsmContainerBlockItem`. */
export function containerBlockItemJava(blockPackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's MsmContainerBlockItem.
package ${blockPackage};

import net.minecraft.world.item.BlockItem;
import net.minecraft.world.level.block.Block;

/**
 * The block item of a keep-contents container (ADR 0074 D6): it carries the contents in its {@code container} component,
 * so, like a shulker box, it cannot go inside another container item ({@code canFitInsideContainerItems} false). The
 * shulker box menu's slots, hoppers ({@link StorageBlockEntity#canPlaceItem}) and bundles refuse it.
 */
public class ContainerBlockItem extends BlockItem {
    public ContainerBlockItem(Block block, Properties properties) {
        super(block, properties);
    }

    @Override
    public boolean canFitInsideContainerItems() {
        return false;
    }
}
`;
}
